mapper.select:

where s.del_flag = '0'
 and s.station_name like concat('%', #{query.stationName}, '%')
 and s.status = #{query.status}
 and s.contact like concat('%', #{query.contact}, '%')
 and s.user_id = #{query.userId}
order by s.station_id


where s.del_flag = '0'
 and s.station_name like concat('%', #{query.stationName}, '%')
 and s.status = #{query.status}
 and s.contact like concat('%', #{query.contact}, '%')
 and s.user_id = #{query.userId}
order by s.station_id

select s.stationCount, s.enabledCount, s.disabledCount, s.totalCapacity, s.avgCapacity, coalesce(r.adjustablePower, 0) as adjustablePower, coalesce(r.valleyPower, 0) as valleyPower, coalesce(r.ratedPower, 0) as ratedPower, coalesce(r.baselinePower, 0) as baselinePower, coalesce(r.pileCount, 0) as pileCount, coalesce(r.dcPileCount, 0) as dcPileCount, coalesce(r.acPileCount, 0) as acPileCount from (select count(*) as stationCount, sum(case when status = '1' then 1 else 0 end) as enabledCount, sum(case when status = '0' then 1 else 0 end) as disabledCount, coalesce(sum(capacity), 0) as totalCapacity, coalesce(round(avg(capacity), 2), 0) as avgCapacity from dr_station where del_flag = '0'
and station_id in #{id}
) s cross join (select coalesce(sum(adjustable_power), 0) as adjustablePower, coalesce(sum(valley_power), 0) as valleyPower, coalesce(sum(rated_power), 0) as ratedPower, coalesce(sum(avg7d_power), 0) as baselinePower, count(resource_id) as pileCount, sum(case when pile_type = 'DC' then 1 else 0 end) as dcPileCount, sum(case when pile_type = 'AC' then 1 else 0 end) as acPileCount from dr_resource where del_flag = '0' and participate_flag = '1'
and station_id in #{id}
) r
